  assert.equal(blockedRun.status, 'blocked');
  assert.deepEqual(blockedRun.blockedNodes, [{ nodeId: 'wrap', missingDependencies: ['standard'] }]);
  assert.equal(blockedRun.context.output.priority, 'p');
