  ['a revoked Proxy', revokedProxy],
  ['a proxy whose prototype read throws', throwingPrototypeProxy],
]) {
  test(`a synchronously thrown ${label} is recorded as a failure, not a rejection`, async () => {
    const value = makeValue();
